<?php
require __DIR__.'/config.php'; require_role(['admin','teacher']);
$students=read_json('students');$subjects=read_json('subjects');$classes=read_json('classes');$results=read_json('results');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$class=(int)$_POST['class_id'];$subject=(int)$_POST['subject_id'];$term=trim($_POST['term']);$assessment=trim($_POST['assessment']);$out=(float)$_POST['out_of'];$marks=$_POST['mark']??[];$comments=$_POST['comment']??[];$now=date('c');
foreach($marks as $sid=>$mark){if($mark===''||!is_numeric($mark))continue;$sid=(int)$sid;$ok=false;foreach($students as $st)if((int)$st['id']===$sid&&(int)($st['class_id']??0)===$class)$ok=true;if(!$ok)continue;$results[]=['id'=>next_id($results),'student_id'=>$sid,'subject_id'=>$subject,'term'=>$term,'assessment'=>$assessment,'mark'=>(float)$mark,'out_of'=>$out,'comment'=>trim($comments[$sid]??''),'created_at'=>$now];}
write_json('results',$results);log_action('bulk_save','results',$class);flash('Class results saved.');redirect('gradebook.php?class_id='.$class.'&subject_id='.$subject.'&term='.urlencode($term));}
$classId=(int)($_GET['class_id']??0);$subjectId=(int)($_GET['subject_id']??0);$term=$_GET['term']??'Term 1';$roster=array_values(array_filter($students,fn($s)=>(int)($s['class_id']??0)===$classId));
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gradebook — Ridgefield</title><link rel="stylesheet" href="cms.css"><style>.wrap{max-width:1200px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.table{width:100%;border-collapse:collapse;margin-top:20px}.table th,.table td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.table input{width:100%;box-sizing:border-box}.note{padding:12px;background:#f1f4f0;border-left:4px solid #b28b45}@media(max-width:800px){.grid{grid-template-columns:1fr}.table{display:block;overflow:auto}}</style><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="rf-dynamic"><div class="wrap"><p><a href="school.php">← School Management</a></p><h1>Teacher Gradebook</h1><p class="note">Enter one assessment for an entire class. Results automatically feed learner progress and reports.</p>
<form method="get"><div class="grid"><label>Class<select name="class_id" required><option value="">Select</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach;?></select></label><label>Subject<select name="subject_id" required><option value="">Select</option><?php foreach($subjects as $x):?><option value="<?=$x['id']?>" <?=$subjectId===$x['id']?'selected':''?>><?=h($x['name'])?></option><?php endforeach;?></select></label><label>Term<select name="term"><?php foreach(['Term 1','Term 2','Term 3','Term 4'] as $t):?><option <?=$term===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select></label><label><button>Load class</button></label></div></form>
<?php if($classId&&$subjectId):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input type="hidden" name="subject_id" value="<?=$subjectId?>"><input type="hidden" name="term" value="<?=h($term)?>"><div class="grid" style="margin-top:18px"><label>Assessment<input name="assessment" required placeholder="Test 1"></label><label>Out of<input type="number" step="0.01" name="out_of" value="100"></label></div><table class="table"><tr><th>Learner</th><th>Mark</th><th>Comment</th></tr><?php foreach($roster as $st):?><tr><td><?=h($st['name'])?></td><td><input type="number" step="0.01" min="0" name="mark[<?=$st['id']?>]"></td><td><input name="comment[<?=$st['id']?>]"></td></tr><?php endforeach;?></table><p><button type="submit">Save class results</button></p></form><?php endif;?></div><script src="assets/dynamic-site.js"></script>
</body></html>